query P46($owner: String!, $name: String!, $pr: Int!, $issue: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    pullRequest(number: $pr) {
      number state mergedAt lastEditedAt body
      closingIssuesReferences(first: 10) { totalCount nodes { number state } }
    }
    issue(number: $issue) {
      number state
      timelineItems(first: 20, itemTypes: [CONNECTED_EVENT, DISCONNECTED_EVENT, CROSS_REFERENCED_EVENT, CLOSED_EVENT]) {
        totalCount
        nodes {
          __typename
          ... on CrossReferencedEvent { createdAt willCloseTarget actor { login __typename } source { __typename ... on PullRequest { number } } }
          ... on ConnectedEvent { createdAt actor { login __typename } subject { __typename ... on PullRequest { number } } }
          ... on DisconnectedEvent { createdAt actor { login __typename } subject { __typename ... on PullRequest { number } } }
          ... on ClosedEvent { createdAt actor { login __typename } closer { __typename ... on PullRequest { number } } }
        }
      }
    }
  }
}

